history = {
    "master": ["a1b2c3d"],
    "feature/auth": ["a1b2c3d", "5b3c2d1"],
}
messages = {"a1b2c3d": "Add app.js entry point and .gitignore", "5b3c2d1": "Add login function"}

def merge(target, source):
    base = history[target]
    incoming = history[source]
    if base == incoming[:len(base)]:
        new_commits = incoming[len(base):]
        history[target] = base + new_commits
        print(f"Updating {base[-1][:7]}..{incoming[-1][:7]}")
        print("Fast-forward")
        for sha in new_commits:
            print(f" {messages[sha]}")
    else:
        merge_sha = "9f8e7d6"
        history[target] = base + [merge_sha]
        messages[merge_sha] = f"Merge branch '{source}' into {target}"
        print(f"Merge made by the 'recursive' strategy.")

merge("master", "feature/auth")
for sha in history["master"]:
    print(f"{sha[:7]} {messages[sha]}")
del history["feature/auth"]
print("Deleted branch feature/auth")
